import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.map.js";
import maplibregl from 'maplibre-gl'; // Nhớ cài đặt maplibre-gl

export default {
  props: {
    selectedLocation: {
      type: Array,
      default: () => [105.85242472181584, 21.029579719995272]
    }
  },
  data() {
    return {
      map: null,
      apiUrl: 'https://rsapi.goong.io',
      mapUrl: 'https://tiles.goong.io/assets/',
      apiKey: 'ArPlUISaEBAdJFTABi9dcNGcue8WQ4cOAuGcNoBE',
      // your API key
      mapKey: 'tLyW2vk0aY3yfQLu8ZPy986mAgaW8igMYufv3BLY',
      // your map key
      center: [105.85242472181584, 21.029579719995272],
      // Kinh độ, vĩ độ
      zoom: 14,
      // Độ zoom mặc định
      radiusInMeters: 100
    };
  },
  mounted() {
    this.initMap();
  },
  watch: {
    selectedLocation: 'moveToLocation'
  },
  methods: {
    initMap() {
      this.map = new maplibregl.Map({
        container: 'map',
        style: `${this.mapUrl}goong_map_web.json?api_key=${this.mapKey}`,
        center: this.selectedLocation,
        zoom: 14
      });
      this.map.on('load', () => {
        const lngLat = [...this.selectedLocation];
        console.log("Vẽ marker tại:", lngLat);

        // Gọi hàm vẽ hình tròn như marker
        this.addCircleAsMarker(lngLat);

        // Di chuyển đến vị trí của hình tròn
        this.map.flyTo({
          center: lngLat,
          zoom: 14
        });
      });
    },
    moveToLocation(newLocation) {
      this.map.flyTo({
        center: newLocation,
        essential: true
      });
      this.addMarkerAndCircleAround(newLocation);
    },
    removeLayer(layerId) {
      if (this.map.getLayer(layerId)) {
        this.map.removeLayer(layerId);
      }
    },
    addMarker(lngLat) {
      new maplibregl.Marker().setLngLat(lngLat).addTo(this.map);
    },
    addCircleAsMarker(lngLat) {
      const circleRadius = this.radiusInMeters;

      // Dữ liệu cho hình tròn
      const circleData = {
        'type': 'FeatureCollection',
        'features': [{
          'type': 'Feature',
          'geometry': {
            'type': 'Point',
            'coordinates': lngLat
          }
        }]
      };

      // Thêm nguồn dữ liệu cho hình tròn
      this.map.addSource('circle', {
        'type': 'geojson',
        'data': circleData
      });

      // Thêm lớp hình tròn vào bản đồ
      this.map.addLayer({
        id: 'circle-layer',
        type: 'circle',
        // Sử dụng loại hình tròn
        source: 'circle',
        paint: {
          'circle-radius': circleRadius / 1000,
          // Điều chỉnh kích thước
          'circle-color': '#FF0000',
          // Màu của hình tròn
          'circle-opacity': 0.6 // Độ trong suốt
        }
      });

      // Thêm hình tam giác để tạo cảm giác như marker
      const triangleData = {
        'type': 'FeatureCollection',
        'features': [{
          'type': 'Feature',
          'geometry': {
            'type': 'Polygon',
            'coordinates': [[[lngLat[0] - 0.0001, lngLat[1] - 0.0001],
            // Điểm dưới trái
            [lngLat[0] + 0.0001, lngLat[1] - 0.0001],
            // Điểm dưới phải
            [lngLat[0], lngLat[1] - 0.0002],
            // Điểm đỉnh
            [lngLat[0] - 0.0001, lngLat[1] - 0.0001] // Quay lại điểm đầu
            ]]
          }
        }]
      };
      this.map.addSource('triangle', {
        'type': 'geojson',
        'data': triangleData
      });
      this.map.addLayer({
        id: 'triangle-layer',
        type: 'fill',
        source: 'triangle',
        paint: {
          'fill-color': '#FF0000',
          // Màu của tam giác
          'fill-opacity': 1 // Độ trong suốt
        }
      });
    },
    addMarkerAndCircleAround(lngLat) {
      // Xóa vòng tròn cũ nếu có
      this.removeLayer('circle');

      // Tạo dữ liệu cho vòng tròn
      const circleData = {
        'type': 'FeatureCollection',
        'features': [{
          'type': 'Feature',
          'geometry': {
            'type': 'Polygon',
            'coordinates': [this.drawCircle(lngLat, this.radiusInMeters)]
          }
        }]
      };

      // Kiểm tra xem nguồn đã tồn tại chưa trước khi thêm
      if (this.map.getSource('circle')) {
        this.map.removeSource('circle');
      }

      // Thêm source cho vòng tròn
      this.map.addSource('circle', {
        'type': 'geojson',
        'data': circleData
      });
      console.log('Source "circle" added:', this.map.getSource('circle'));

      // Thêm layer cho vòng tròn
      this.map.addLayer({
        'id': 'circle',
        'type': 'fill',
        'source': 'circle',
        'layout': {},
        'paint': {
          'fill-color': '#588888',
          'fill-opacity': 0.5
        }
      });
      console.log('Layer "circle" added:', this.map.getLayer('circle'));

      // Di chuyển đến vị trí mới
      this.map.flyTo({
        center: lngLat,
        zoom: 14
      }); // Bạn có thể điều chỉnh zoom ở đây
    },
    drawCircle(center, radius) {
      const points = 64; // Số điểm để vẽ vòng tròn
      const coords = [];
      for (let i = 0; i <= points; i++) {
        const angle = i / points * 2 * Math.PI; // Tính toán góc
        const dx = radius * Math.cos(angle); // Tính toán độ dịch chuyển theo kinh độ
        const dy = radius * Math.sin(angle); // Tính toán độ dịch chuyển theo vĩ độ
        coords.push([center[0] + dx / 111320,
        // Kinh độ
        center[1] + dy / 110574 // Vĩ độ
        ]);
      }
      coords.push(coords[0]); // Đảm bảo vòng tròn khép kín

      return coords;
    }
  }
};
